function e(n){if(!n)return"";const t=Date.now()-new Date(n).getTime();if(!Number.isFinite(t))return"";if(t<6e4)return"just now";if(t<36e5){const r=Math.max(1,Math.floor(t/6e4));return`${r} minute${r===1?"":"s"} ago`}if(t<864e5){const r=Math.floor(t/36e5);return`${r} hour${r===1?"":"s"} ago`}if(t<2592e6){const r=Math.floor(t/864e5);return`${r} day${r===1?"":"s"} ago`}if(t<31536e6){const r=Math.floor(t/2592e6);return`${r} month${r===1?"":"s"} ago`}const o=Math.floor(t/31536e6);return`${o} year${o===1?"":"s"} ago`}function f(n){if(!n)return"";const t=Date.now()-new Date(n).getTime();return!Number.isFinite(t)||t<6e4?"now":t<36e5?`${Math.floor(t/6e4)}m`:t<864e5?`${Math.floor(t/36e5)}h`:t<2592e6?`${Math.floor(t/864e5)}d`:t<31536e6?`${Math.floor(t/2592e6)}mo`:`${Math.floor(t/31536e6)}y`}export{f as a,e as r};
